-- India deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, penalty rows, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (IRP)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los umbrales de facturación, los requisitos técnicos del IRP y las disposiciones sobre sanciones continúan evolucionando — confirme los requisitos actuales directamente en el portal de e-Invoice del GST o con un profesional del GST antes de construir una integración.', 'India implementó la facturación electrónica reduciendo progresivamente el umbral de facturación — una ampliación gradual del alcance en lugar de un mandato de un único día señalado.', 'La factura electrónica de India es un documento JSON, no XML — una distinción que vale la pena señalar, ya que gran parte del resto del mundo utiliza XML por defecto.', 'Cuatro instituciones comparten la responsabilidad del funcionamiento de este sistema — conviene saber quién hace qué cuando algo falla.', 'El registro es sencillo si ya es una empresa registrada en el GST — el verdadero trabajo consiste en construir o conectar su canal de envío al IRP.', 'El mayor riesgo práctico no es la multa en sí — es que una factura sin un IRN válido no es legalmente una factura GST válida en absoluto.' FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentrales Clearing (IRP)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Umsatzschwellen, technische IRP-Anforderungen und Strafvorschriften entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt auf dem GST-e-Invoice-Portal oder bei einem GST-Berater, bevor Sie eine Integration aufbauen.', 'Indien führte die E-Rechnungsstellung durch schrittweise Senkung der Umsatzschwelle ein — eine allmähliche Ausweitung des Anwendungsbereichs statt eines einzigen Stichtags-Mandats.', 'Indiens E-Rechnung ist ein JSON-Dokument, kein XML-Dokument — ein Unterschied, den man hervorheben sollte, da der Großteil der übrigen Welt standardmäßig auf XML setzt.', 'Vier Institutionen teilen sich die Verantwortung für den Betrieb dieses Systems — es lohnt sich zu wissen, wer was tut, wenn etwas schiefgeht.', 'Die Registrierung ist unkompliziert, wenn Sie bereits ein GST-registriertes Unternehmen sind — die eigentliche Arbeit besteht darin, Ihre IRP-Übermittlungs-Pipeline aufzubauen oder anzubinden.', 'Das größere praktische Risiko ist nicht die Geldstrafe selbst — es ist, dass eine Rechnung ohne gültige IRN rechtlich überhaupt keine gültige GST-Rechnung ist.' FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (IRP)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les seuils de chiffre d''affaires, les exigences techniques de l''IRP et les dispositions relatives aux pénalités continuent d''évoluer — confirmez les exigences actuelles directement sur le portail e-Invoice du GST ou auprès d''un praticien GST avant de construire une intégration.', 'L''Inde a déployé la facturation électronique en abaissant progressivement le seuil de chiffre d''affaires — un élargissement graduel du champ d''application plutôt qu''un mandat à date unique.', 'La facture électronique indienne est un document JSON, et non XML — une distinction qui mérite d''être soulignée puisque la majeure partie du reste du monde utilise le XML par défaut.', 'Quatre institutions se partagent la responsabilité du fonctionnement de ce système — il est utile de savoir qui fait quoi lorsque quelque chose ne va pas.', 'L''inscription est simple si vous êtes déjà une entreprise enregistrée à la GST — le vrai travail consiste à construire ou connecter votre pipeline de soumission à l''IRP.', 'Le risque pratique le plus important n''est pas l''amende elle-même — c''est qu''une facture sans IRN valide n''est légalement pas du tout une facture GST valide.' FROM countries WHERE name_en = 'India';

