INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Esquema', '[["Formato", "Formulario GST INV-01 (esquema v1.1)"], ["Sintaxis", "JSON"], ["Códigos maestros", "HSN, país, moneda, códigos de estado"]]', 'Las personas registradas siguen creando facturas GST en sus propios sistemas de contabilidad/facturación/ERP como antes — el cambio es que ahora estas facturas deben reportarse a un IRP antes de tener fuerza legal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Schema', '[["Format", "Formular GST INV-01 (Schema v1.1)"], ["Syntax", "JSON"], ["Stammcodes", "HSN-, Länder-, Währungs-, Bundesstaatencodes"]]', 'Registrierte Personen erstellen GST-Rechnungen weiterhin wie bisher in ihren eigenen Buchhaltungs-/Abrechnungs-/ERP-Systemen — die Änderung besteht darin, dass diese Rechnungen nun vor Erlangung der Rechtskraft an ein IRP gemeldet werden müssen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Schéma', '[["Format", "Formulaire GST INV-01 (schéma v1.1)"], ["Syntaxe", "JSON"], ["Codes maîtres", "Codes HSN, pays, devise, état"]]', 'Les personnes enregistrées continuent de créer des factures GST dans leurs propres systèmes comptables/de facturation/ERP comme auparavant — le changement est que ces factures doivent désormais être déclarées à un IRP avant d''avoir force légale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que "facturación electrónica" realmente significa aquí', '[["Concepto erróneo común", "El gobierno genera la factura"], ["Realidad", "La empresa la genera; el IRP la valida y la registra"]]', 'La GSTN es explícita en este punto en sus propias preguntas frecuentes: la facturación electrónica no significa que la factura sea generada por un portal gubernamental — significa reportarla al IRP y obtener un IRN.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was "E-Rechnungsstellung" hier tatsächlich bedeutet', '[["Häufiges Missverständnis", "Die Regierung erstellt die Rechnung"], ["Realität", "Das Unternehmen erstellt sie; das IRP validiert und registriert sie"]]', 'Die GSTN ist in ihren eigenen FAQ zu diesem Punkt eindeutig: E-Rechnungsstellung bedeutet nicht, dass eine Rechnung von einem Regierungsportal erstellt wird — es bedeutet die Meldung an das IRP und den Erhalt einer IRN.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce que la « facturation électronique » signifie réellement ici', '[["Idée reçue courante", "Le gouvernement génère la facture"], ["Réalité", "L''entreprise la génère ; l''IRP la valide et l''enregistre"]]', 'La GSTN est explicite sur ce point dans sa propre FAQ : la facturation électronique ne signifie pas que la facture est générée par un portail gouvernemental — cela signifie la déclarer à l''IRP et obtenir un IRN.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'El propio IRN', '[["Qué es", "Un hash calculado por el IRP"], ["Regla de validez", "Una factura GST solo es válida con un IRN válido"]]', 'El hash que el IRP calcula sobre los datos de su factura se convierte en el Número de Referencia de Factura — esto es lo que hace que el IRN sea a prueba de manipulaciones por construcción, no solo por política.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die IRN selbst', '[["Was es ist", "Ein vom IRP berechneter Hash"], ["Gültigkeitsregel", "Eine GST-Rechnung ist nur mit einer gültigen IRN gültig"]]', 'Der Hash, den das IRP über Ihre Rechnungsdaten berechnet, wird zur Invoice Reference Number — dies macht die IRN von Natur aus manipulationssicher, nicht nur durch Richtlinie.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'L''IRN elle-même', '[["Ce que c''est", "Un hachage calculé par l''IRP"], ["Règle de validité", "Une facture GST n''est valide qu''avec un IRN valide"]]', 'Le hachage que l''IRP calcule sur les données de votre facture devient le numéro de référence de facture — c''est ce qui rend l''IRN infalsifiable par construction, et non simplement par politique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Contenido del código QR', '[["Datos incluidos", "GSTIN del vendedor y comprador, número/fecha de factura, número de líneas, HSN de la mercancía principal, hash"], ["Requisito de impresión", "Obligatorio en la factura (Regla 46, Reglas del CGST)"], ["Impresión del IRN", "Opcional — ya está incrustado en el código QR"]]', 'No está permitido imprimir el código QR en papel separado — debe aparecer en la propia factura como una de las menciones obligatorias.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'QR-Code-Inhalt', '[["Enthaltene Daten", "GSTIN von Verkäufer & Käufer, Rechnungsnummer/-datum, Anzahl der Positionen, HSN der Hauptware, Hash"], ["Druckpflicht", "Verpflichtend auf der Rechnung (Regel 46, CGST-Regeln)"], ["IRN-Druck", "Optional — bereits im QR-Code eingebettet"]]', 'Das Drucken des QR-Codes auf separatem Papier ist nicht zulässig — er muss auf der Rechnung selbst als eine der Pflichtangaben erscheinen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Contenu du code QR', '[["Données incluses", "GSTIN du vendeur et de l''acheteur, numéro/date de facture, nombre de lignes, HSN du produit principal, hachage"], ["Exigence d''impression", "Obligatoire sur la facture (règle 46, règles CGST)"], ["Impression de l''IRN", "Facultative — déjà intégrée dans le code QR"]]', 'Il n''est pas permis d''imprimer le code QR sur papier séparé — il doit apparaître sur la facture elle-même comme l''une des mentions obligatoires.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Instituciones reguladoras', '[["Consejo del GST", "Establece la orientación política, recomienda cambios de umbral"], ["CBIC", "Traduce las recomendaciones en notificaciones vinculantes"], ["GSTN", "Construye y mantiene la infraestructura informática"], ["IRP", "Varios portales autorizados procesan y registran facturas"]]', 'La Junta Central de Impuestos Indirectos y Aduanas (CBIC) es el organismo que efectivamente emite las notificaciones legales vinculantes — la GSTN construye la tecnología subyacente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Regelnde Institutionen', '[["GST-Rat", "Legt die politische Richtung fest, empfiehlt Schwellenänderungen"], ["CBIC", "Setzt Empfehlungen in verbindliche Bekanntmachungen um"], ["GSTN", "Baut und pflegt die IT-Infrastruktur"], ["IRPs", "Mehrere autorisierte Portale verarbeiten und registrieren Rechnungen"]]', 'Das Central Board of Indirect Taxes and Customs (CBIC) ist die Stelle, die tatsächlich die verbindlichen gesetzlichen Bekanntmachungen erlässt — die GSTN baut die dahinterliegende Technologie.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Institutions régulatrices', '[["Conseil du GST", "Fixe l''orientation politique, recommande les changements de seuil"], ["CBIC", "Traduit les recommandations en notifications contraignantes"], ["GSTN", "Construit et maintient l''infrastructure informatique"], ["IRP", "Plusieurs portails autorisés traitent et enregistrent les factures"]]', 'Le Central Board of Indirect Taxes and Customs (CBIC) est l''organisme qui émet réellement les notifications juridiques contraignantes — la GSTN construit la technologie sous-jacente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Canales de envío', '[["Directo", "Subida directa a un IRP"], ["Vía intermediario", "A través de un Proveedor de Suvidha del GST (GSP)"], ["¿Sin software?", "Herramientas gratuitas autorizadas por la GSTN, o la herramienta de generación masiva sin conexión"]]', 'Las pequeñas y medianas empresas sin su propio ERP o software de facturación realmente no quedan excluidas — existen herramientas gratuitas específicamente para este caso.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Übermittlungskanäle', '[["Direkt", "Direktes Hochladen zu einem IRP"], ["Über Vermittler", "Über einen GST Suvidha Provider (GSP)"], ["Keine Software?", "Kostenlose GSTN-zugelassene Tools oder das Offline-Massengenerierungstool"]]', 'Kleine und mittlere Steuerpflichtige ohne eigenes ERP- oder Abrechnungssoftware werden wirklich nicht ausgeschlossen — kostenlose Tools existieren speziell für diesen Fall.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Canaux de soumission', '[["Direct", "Téléversement direct vers un IRP"], ["Via intermédiaire", "Par l''intermédiaire d''un fournisseur GST Suvidha (GSP)"], ["Pas de logiciel ?", "Outils gratuits agréés par la GSTN, ou l''outil de génération groupée hors ligne"]]', 'Les petits et moyens contribuables sans ERP ou logiciel de facturation propre ne sont vraiment pas laissés pour compte — des outils gratuits existent spécifiquement pour ce cas.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Los efectos de la regla de 30 días', '[["Se aplica a", "AATO ≥ ₹10 crore"], ["Efecto", "Las facturas de más de 30 días son rechazadas directamente por el IRP"]]', 'No se trata de una situación de recargo por retraso — pasada esta ventana, la factura simplemente no puede registrarse en absoluto, y las facturas pasadas no pueden registrarse retroactivamente si se incumplió el plazo anteriormente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die Konsequenzen der 30-Tage-Regel', '[["Gilt für", "AATO ≥ ₹10 Crore"], ["Wirkung", "Rechnungen, die älter als 30 Tage sind, werden vom IRP direkt abgelehnt"]]', 'Dies ist keine Situation mit Verzugsgebühr — nach diesem Fenster kann die Rechnung schlicht nicht mehr registriert werden, und vergangene Rechnungen können nicht rückwirkend registriert werden, wenn die Frist zuvor verpasst wurde.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Les conséquences de la règle des 30 jours', '[["S''applique à", "AATO ≥ ₹10 crore"], ["Effet", "Les factures de plus de 30 jours sont rejetées d''emblée par l''IRP"]]', 'Il ne s''agit pas d''une situation de pénalité de retard — passé ce délai, la facture ne peut tout simplement plus être enregistrée du tout, et les factures passées ne peuvent pas être enregistrées rétroactivement si la conformité a été manquée auparavant.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación', 'Cada factura pasa por la misma secuencia:', 'Tras el registro exitoso, los datos se rellenan automáticamente en la declaración GSTR-1 del proveedor — una genuina simplificación posterior del cumplimiento, no solo una formalidad.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Clearing-Ablauf', 'Jede Rechnung durchläuft dieselbe Abfolge:', 'Nach erfolgreicher Registrierung werden die Daten automatisch in die GSTR-1-Erklärung des Lieferanten übernommen — eine echte nachgelagerte Compliance-Vereinfachung, nicht nur eine Formalität.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle', 'Chaque facture suit la même séquence :', 'Après un enregistrement réussi, les données alimentent automatiquement la déclaration GSTR-1 du fournisseur — une véritable simplification de la conformité en aval, et non une simple formalité.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'India';

