INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su facturación agregada en todos los GSTIN', 'Compruebe su facturación combinada bajo un único PAN — solo necesita superar ₹5 crore una vez en cualquier ejercicio fiscal desde 2017–18 para quedar permanentemente dentro del alcance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihren aggregierten Umsatz über alle GSTINs', 'Prüfen Sie Ihren kombinierten Umsatz unter einer einzigen PAN — er muss nur einmal in einem Geschäftsjahr seit 2017–18 ₹5 Crore überschreiten, um Sie dauerhaft in den Anwendungsbereich zu bringen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre chiffre d''affaires agrégé sur tous les GSTIN', 'Vérifiez votre chiffre d''affaires combiné sous un seul PAN — il ne doit dépasser ₹5 crore qu''une seule fois au cours d''un exercice fiscal depuis 2017–18 pour vous faire entrer définitivement dans le champ d''application.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Active la facturación electrónica en el portal del GST si no está habilitada automáticamente', 'Si su facturación ha superado el umbral pero no ha sido habilitado automáticamente, use Registro → Habilitación de e-Invoice para activarla voluntariamente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Aktivieren Sie die E-Rechnungsstellung auf dem GST-Portal, falls nicht automatisch aktiviert', 'Wenn Ihr Umsatz die Schwelle überschritten hat, Sie aber nicht automatisch aktiviert wurden, nutzen Sie Registrierung → e-Invoice-Aktivierung, um sie freiwillig einzuschalten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Activez la facturation électronique sur le portail GST si elle n''est pas activée automatiquement', 'Si votre chiffre d''affaires a dépassé le seuil mais que vous n''avez pas été activé automatiquement, utilisez Inscription → Activation e-Invoice pour l''activer volontairement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su canal de envío', 'Subida directa al IRP, un Proveedor de Suvidha del GST, o — si carece de ERP/software de facturación — una herramienta gratuita autorizada por la GSTN o la utilidad de generación masiva sin conexión.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Übermittlungskanal', 'Direktes IRP-Hochladen, ein GST Suvidha Provider oder — falls Sie kein ERP/Abrechnungssoftware haben — ein kostenloses GSTN-zugelassenes Tool oder das Offline-Massengenerierungstool.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre canal de soumission', 'Téléversement direct vers l''IRP, un fournisseur GST Suvidha, ou — si vous n''avez pas d''ERP/logiciel de facturation — un outil gratuit agréé par la GSTN ou l''utilitaire de génération groupée hors ligne.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Active la autenticación multifactor', 'Obligatoria en el portal del GST para AATO superior a ₹100 crore desde mediados de 2023, y para AATO ≥ ₹10 crore desde abril de 2025 — confirme que su configuración de acceso cumple el requisito para su tramo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Aktivieren Sie die Multi-Faktor-Authentifizierung', 'Verpflichtend auf dem GST-Portal für AATO über ₹100 Crore seit Mitte 2023, und für AATO ≥ ₹10 Crore seit April 2025 — bestätigen Sie, dass Ihre Zugangskonfiguration die Anforderung für Ihre Klasse erfüllt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Activez l''authentification multifacteur', 'Obligatoire sur le portail GST pour un AATO supérieur à ₹100 crore depuis mi-2023, et pour un AATO ≥ ₹10 crore depuis avril 2025 — confirmez que votre configuration d''accès répond à l''exigence de votre tranche.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Integre la ventana de reporte de 30 días en su flujo de trabajo', 'Si su AATO es ≥ ₹10 crore, automatice el envío bien dentro de los 30 días posteriores a la emisión — no hay forma de registrar una factura después de que se cierre esa ventana.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Integrieren Sie das 30-Tage-Meldefenster in Ihren Workflow', 'Wenn Ihr AATO ≥ ₹10 Crore ist, automatisieren Sie die Übermittlung deutlich innerhalb von 30 Tagen nach Ausstellung — nach Schließen dieses Fensters gibt es keinen Weg mehr, eine Rechnung zu registrieren.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez la fenêtre de déclaration de 30 jours dans votre flux de travail', 'Si votre AATO est ≥ ₹10 crore, automatisez la soumission bien avant les 30 jours suivant l''émission — il n''y a aucun moyen d''enregistrer une facture après la fermeture de cette fenêtre.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si ha incumplido, actúe de inmediato en lugar de retroactivamente', 'Las facturas pasadas no pueden registrarse a posteriori. Comience la generación conforme para todas las nuevas facturas ahora, y consulte a un profesional del GST sobre la divulgación voluntaria para el período no conforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie die Compliance verpasst haben, handeln Sie sofort statt rückwirkend', 'Vergangene Rechnungen können nicht nachträglich registriert werden. Beginnen Sie jetzt mit der konformen Erstellung aller neuen Rechnungen und konsultieren Sie einen GST-Berater bezüglich freiwilliger Offenlegung für den nicht konformen Zeitraum.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous avez manqué la conformité, agissez immédiatement plutôt que rétroactivement', 'Les factures passées ne peuvent pas être enregistrées après coup. Commencez dès maintenant la génération conforme pour toutes les nouvelles factures, et consultez un praticien GST au sujet de la divulgation volontaire pour la période de non-conformité.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'India' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'es', 'Incumplimiento en la generación de una factura electrónica requerida', 'Sanción bajo las disposiciones de incumplimiento de la Ley CGST, vinculada al impuesto involucrado', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'de', 'Nichterstellung einer erforderlichen E-Rechnung', 'Strafe gemäß den Nichteinhaltungsbestimmungen des CGST-Gesetzes, gekoppelt an die betroffene Steuer', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'Non-génération d''une facture électronique requise', 'Sanction en vertu des dispositions de non-conformité de la loi CGST, liée à la taxe concernée', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'es', 'Factura electrónica incorrecta o inválida', 'Sanción separada por facturación incorrecta bajo la ley del GST', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'de', 'Falsche oder ungültige E-Rechnung', 'Separate Strafe für fehlerhafte Rechnungsstellung nach GST-Recht', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'Facture électronique incorrecte ou invalide', 'Sanction distincte pour facturation incorrecte en vertu de la loi GST', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'India' AND dpr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '⚠️ La invalidez es el riesgo más agudo', NULL, NULL, 'Una factura emitida sin un IRN no es legalmente una factura GST — más allá de cualquier multa monetaria, esto puede bloquear por completo la reclamación de crédito fiscal del comprador, una consecuencia comercial mucho más disruptiva que la cifra de la sanción en sí.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '⚠️ Ungültigkeit ist das schärfere Risiko', NULL, NULL, 'Eine ohne IRN ausgestellte Rechnung ist rechtlich keine GST-Rechnung — über jede Geldstrafe hinaus kann dies die Vorsteuerabzugsforderung des Käufers vollständig blockieren, eine weitaus disruptivere geschäftliche Konsequenz als der Strafbetrag selbst.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '⚠️ L''invalidité est le risque le plus aigu', NULL, NULL, 'Une facture émise sans IRN n''est légalement pas une facture GST — au-delà de toute amende pécuniaire, cela peut bloquer entièrement la demande de crédit de taxe intrant de l''acheteur, une conséquence commerciale bien plus perturbatrice que le montant de la sanction elle-même.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔒 Sin corrección retroactiva', NULL, NULL, 'Si el cumplimiento se incumplió en un período pasado, esas facturas permanecen permanentemente inválidas — esto hace que detectar una brecha de cumplimiento a tiempo sea mucho más valioso que en regímenes que permiten la corrección retroactiva.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔒 Keine rückwirkende Korrektur', NULL, NULL, 'Wenn die Compliance in einem vergangenen Zeitraum verpasst wurde, bleiben diese Rechnungen dauerhaft ungültig — dies macht das frühzeitige Erkennen einer Compliance-Lücke weitaus wertvoller als in Systemen, die eine rückwirkende Korrektur zulassen.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔒 Aucune correction rétroactive', NULL, NULL, 'Si la conformité a été manquée au cours d''une période passée, ces factures restent définitivement invalides — cela rend la détection précoce d''un écart de conformité bien plus précieuse que dans les régimes autorisant une correction rétroactive.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📉 Vigile nuevas reducciones del umbral', NULL, NULL, 'Dada la trayectoria de ₹500 crore a ₹5 crore en cinco años, nuevas reducciones (algunas discusiones han sugerido ₹2 crore) siguen siendo plausibles — no asuma que el umbral actual es permanente.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📉 Achten Sie auf weitere Schwellenreduzierungen', NULL, NULL, 'Angesichts des Verlaufs von ₹500 Crore auf ₹5 Crore über fünf Jahre bleiben weitere Reduzierungen (in einigen Diskussionen wurden ₹2 Crore genannt) plausibel — gehen Sie nicht davon aus, dass die aktuelle Schwelle dauerhaft ist.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📉 Surveillez de nouvelles réductions de seuil', NULL, NULL, 'Compte tenu de la trajectoire de ₹500 crore à ₹5 crore en cinq ans, de nouvelles réductions (certaines discussions ont évoqué ₹2 crore) restent plausibles — ne présumez pas que le seuil actuel est permanent.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'e-Invoice / IRP (NIC)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'India' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'e-Invoice / IRP (NIC)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'India' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'e-Invoice / IRP (NIC)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'India' AND dp.sort_order = 0;
